import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.doxMM-x8.js";const p=JSON.parse('{"title":"维护项目文档","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/guides/documentation","contentType":"guide","prev":false,"next":{"text":"发布文档","link":"/getting-started/publish-docs"}},"headers":[],"relativePath":"guides/documentation.md","filePath":"guides/documentation.md"}'),o={name:"guides/documentation.md"};function n(i,t,s,l,c,b){return a(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="维护项目文档" tabindex="-1">维护项目文档 <a class="header-anchor" href="#维护项目文档" aria-label="Permalink to &quot;维护项目文档&quot;">​</a></h1><p>目标：随 Lab Word 功能交付可跟做、可查阅的文档。写作模式参考 <a href="https://github.com/CaiZongyuan/axum-saas-template/tree/83f1f71bd166af8b604dd50124abc85242b82177/docs" target="_blank" rel="noreferrer">axum-saas-template</a> 在 2026-10-01 的版本；主题与事实来自 Lab Word 当前源码。</p><h2 id="先确定读者任务" tabindex="-1">先确定读者任务 <a class="header-anchor" href="#先确定读者任务" aria-label="Permalink to &quot;先确定读者任务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>内容顺序</th><th>完成条件</th></tr></thead><tbody><tr><td>教程</td><td>开发目标、前章状态、完整变更、运行、结果、失败检查、下一章</td><td>同一份 Lab 代码可以继续下一步</td></tr><tr><td>指南</td><td>目标、前提、源码和公共接口、最小完整操作、验证、恢复</td><td>从本页独立进入也能完成任务</td></tr><tr><td>概念</td><td>定义、实际关系图、最小例子、取舍、边界、实践入口</td><td>能理解何时使用与失败范围</td></tr><tr><td>参考</td><td>事实来源、分类、参数、返回、错误、限制、使用链接</td><td>能查到当前合同</td></tr><tr><td>概览</td><td>产品范围、当前阶段、任务入口、首个结果</td><td>读者知道从哪里开始</td></tr></tbody></table><p>设备查看、GLB 导入和 Lab 开发是自己的学习路径。平台知识按 Lab 真正需要的能力链接；历史模板工单、SaaS 课程和模板推广内容不作为产品文档。</p><h2 id="写一条可验证路径" tabindex="-1">写一条可验证路径 <a class="header-anchor" href="#写一条可验证路径" aria-label="Permalink to &quot;写一条可验证路径&quot;">​</a></h2><p>先检查公开接口与实际源码，再写“文件位置 → 完整操作 → 命令 → 观察结果 → 一个失败与恢复”。注明执行目录、依赖、占位值及是否写入持久数据。先让读者得到结果，再解释原因。</p><p>明确区分正式实现、隔离预览和计划。截图应来自实际版本，记录身份与数据是否模拟。页脚 SHA 表示构建源码，不能代替运行与教学验证。</p><h2 id="simplified-technical-language" tabindex="-1">简明技术语言：ASD-STE100-inspired <a class="header-anchor" href="#simplified-technical-language" aria-label="Permalink to &quot;简明技术语言：ASD-STE100-inspired {#simplified-technical-language}&quot;">​</a></h2><p>在线文档采用 <strong>80% of the way to ASD-STE100</strong> 的写作目标。参考 <a href="https://www.asd-ste100.org/" target="_blank" rel="noreferrer">ASD-STE100 Simplified Technical English</a> 的简明技术英语原则，让操作、条件和结果更容易理解。“80%”表示借鉴程度，不是可计算的合规分数；本项目不声明完整符合其写作规则或受控词典。</p><table tabindex="0"><thead><tr><th>规则</th><th>在 Lab Word 文档中如何使用</th></tr></thead><tbody><tr><td>短句，一个句子一个主要意思</td><td>英文操作句以不超过 20 词、说明句以不超过 25 词为目标；过长时先拆句。中文按意思拆句，不套用英文词数。</td></tr><tr><td>主动语态，明确执行者</td><td>操作用动词开头，例如 <code>Open</code>、<code>Run</code>、<code>Select</code>；描述行为时指出 API、Worker 或浏览器做什么。</td></tr><tr><td>一步一个动作</td><td>把操作写成编号步骤，紧接预期结果。依赖、权限、条件和警告放在相关动作之前。</td></tr><tr><td>常用词，稳定含义</td><td>优先使用 <code>use</code>、<code>start</code>、<code>stop</code>、<code>check</code>。同一概念使用同一术语，领域词汇以 <a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/CONTEXT.md" target="_blank" rel="noreferrer">CONTEXT</a> 为准。</td></tr><tr><td>保留准确的技术名称</td><td>保留 GLB、Entity 等必要术语，并在首次使用时解释。命令、路径、API 字段、错误码和界面标签保持原样。</td></tr><tr><td>条件和失败可直接判断</td><td>写明触发条件、结果和恢复动作。保留 <code>must</code>、<code>should</code>、<code>can</code> 的约束差别、否定含义、单位、数值范围及权限边界。</td></tr></tbody></table><p>每段围绕一个主题；把操作与解释分开。中英文保留相同的前提、步骤、结果和失败边界，句式可以各自自然表达。</p><p>例如，把 “After adding SQL, migrate and restart development so the embedded migration set is refreshed.” 改成：</p><ol><li>After you append a SQL migration, run <code>pnpm server migrate</code>.</li><li>Restart development.</li></ol><p>Restart the service to load the new migration set.</p><p>提交前逐段核对上表，并与源码和另一语言版本比较。词数是编辑提示，不能代替语义审查。<code>docs:check</code> 检查文档结构与来源关系，不验证 STE 合规性。</p><h2 id="登记与验证" tabindex="-1">登记与验证 <a class="header-anchor" href="#登记与验证" aria-label="Permalink to &quot;登记与验证&quot;">​</a></h2><p>在中文文件旁创建 <code>.en.md</code>，在 <a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/docs/site.json" target="_blank" rel="noreferrer">site.json</a>登记稳定 id、两组标题与 source、发布 route、group 和 type。连续章节用 <code>previous</code>/<code>next</code> 的 id；不相关页面不自动串联。</p><p>Markdown 为正文来源；API 来自正式 Node Zod/OpenAPI，配置来自运行 Node parser。受检查的完整源码可用 <code>&lt;&lt;&lt;</code> 引用，避免复制第二份代码。<code>apps/docs/.generated</code> 与构建产物由脚本生成；站点图片放在 <code>apps/docs/public/</code>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e:docs</span></span></code></pre></div><p>前两项检查正文来源、双语关系、生成参考和构建链接；浏览器验证语言、主题、搜索和部署 base。业务 HTTP、组件及实际三维渲染分别按<a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/docs/testing/strategy.md" target="_blank" rel="noreferrer">测试策略</a>验证。</p><p>Lab Word 尚未发布继承模板的教学路径，清理时已移除无关页面；保留已采用页面的稳定 route。以后重组已发布的 Lab 页面时维护真实旧链接，避免从旧模板移植悬空导航。</p><h2 id="维护入口" tabindex="-1">维护入口 <a class="header-anchor" href="#维护入口" aria-label="Permalink to &quot;维护入口&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/CONTEXT.md" target="_blank" rel="noreferrer">CONTEXT</a>维护词汇，<a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/docs/adr/0005-lab-digital-twin-on-saas-foundation.md" target="_blank" rel="noreferrer">ADR 0005</a>记录产品边界，<a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/docs/agents/development-flow.md" target="_blank" rel="noreferrer">开发流程</a>与<a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/docs/agents/documentation.md" target="_blank" rel="noreferrer">作者规则</a>约束交付。原有<a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/docs/document-guild.md" target="_blank" rel="noreferrer">文档理念</a>保留为写作参考。</p><p>完成验证后按<a href="./../getting-started/publish-docs">发布指南</a>处理线上站点。</p><hr><p>源码版本：<code>a10b900dc66b</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/docs/guides/maintain-docs.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,27)])])}const f=e(o,[["render",n]]);export{p as __pageData,f as default};
